    static func palette(_ rarity: ChestRarity) -> [Key: UInt32] {
        switch rarity {
        case .wood: return [.bodyBottom: 0x6A3B18, .bodyTop: 0xA8692F, .gem: 0xFFFFFF, .gemDark: 0xFFFFFF, .gemLight: 0xFFFFFF, .glow: 0xFFC56B, .glowWhite: 0xFFFFFF, .grain: 0x5C3414, .inner: 0x482910, .interior: 0x1A0D04, .keyhole: 0x2A1608, .lidBottom: 0x6E4019, .lidMid: 0x9C6030, .lidTop: 0xC88645, .lock: 0xE0AE3E, .lockDark: 0x7A5412, .lockLight: 0xFFE9A0, .metal: 0x9AA1AC, .metalDark: 0x4E545E, .metalLight: 0xE4E8EE, .outline: 0x2A1608, .plank: 0x4A2810, .rivet: 0x6D737D, .rivetHi: 0xF4F6F9, .rune: 0xFFC66B]
        case .silver: return [.bodyBottom: 0x4A5B80, .bodyTop: 0x8FA2C4, .gem: 0x49B6F5, .gemDark: 0x1A5C9E, .gemLight: 0xD8F3FF, .glow: 0xD4ECFF, .glowWhite: 0xFFFFFF, .grain: 0x34446A, .inner: 0x323F5E, .interior: 0x0E1420, .keyhole: 0x1C2433, .lidBottom: 0x4F6290, .lidMid: 0x7E92B8, .lidTop: 0xB9C8E2, .lock: 0xAEBBD0, .lockDark: 0x4E5A70, .lockLight: 0xFFFFFF, .metal: 0x8E9BB0, .metalDark: 0x465269, .metalLight: 0xFFFFFF, .outline: 0x1E2638, .plank: 0x34446A, .rivet: 0x5C6880, .rivetHi: 0xFFFFFF, .rune: 0xBFE6FF]
        case .gold: return [.bodyBottom: 0xC2830E, .bodyTop: 0xFFD34D, .gem: 0xE3243B, .gemDark: 0x7A0A1A, .gemLight: 0xFFC2C2, .glow: 0xFFE47E, .glowWhite: 0xFFFFFF, .grain: 0x9A6206, .inner: 0x784D07, .interior: 0x2A1600, .keyhole: 0x3D2200, .lidBottom: 0xB87A0C, .lidMid: 0xF5BC2E, .lidTop: 0xFFEC8F, .lock: 0xF1C64A, .lockDark: 0x8A5A00, .lockLight: 0xFFFBE6, .metal: 0xB4701A, .metalDark: 0x5E3604, .metalLight: 0xFFE7B0, .outline: 0x3D2200, .plank: 0x9A6206, .rivet: 0x7A4A08, .rivetHi: 0xFFF6D6, .rune: 0xFFE27A]
        case .magic: return [.bodyBottom: 0x3A1B99, .bodyTop: 0x7E50F2, .gem: 0xFF4FCB, .gemDark: 0x8A0F6A, .gemLight: 0xFFD6F4, .glow: 0xDAA8FF, .glowWhite: 0xFFFFFF, .grain: 0x28106E, .inner: 0x2B1472, .interior: 0x12063A, .keyhole: 0x1A0A45, .lidBottom: 0x40209F, .lidMid: 0x6E44E6, .lidTop: 0xA985FF, .lock: 0xD6C4FF, .lockDark: 0x5D40B0, .lockLight: 0xFFFFFF, .metal: 0xB9A3F2, .metalDark: 0x56399E, .metalLight: 0xFBF5FF, .outline: 0x1A0A45, .plank: 0x28106E, .rivet: 0x6A4CC0, .rivetHi: 0xFFFFFF, .rune: 0x72F2FF]
        case .legendary: return [.bodyBottom: 0x140A2B, .bodyTop: 0x35215C, .gem: 0x7CF7FF, .gemDark: 0x7A3CFF, .gemLight: 0xE8FFFF, .glow: 0xFFB8F0, .glowWhite: 0xFFFFFF, .grain: 0x0A0418, .inner: 0x120826, .interior: 0x0A0316, .keyhole: 0x0C0518, .lidBottom: 0x190D33, .lidMid: 0x2F1C58, .lidTop: 0x54388F, .lock: 0xF6CE55, .lockDark: 0x8F6200, .lockLight: 0xFFFBEA, .metal: 0xF2C443, .metalDark: 0x8F6200, .metalLight: 0xFFF6CC, .outline: 0x0C0518, .plank: 0x0A0418, .rivet: 0xA87A10, .rivetHi: 0xFFFBE8, .rune: 0xFFD86B]
        }
