    static let palettes: [ChestRarity: [Key: Color]] = {
        var out: [ChestRarity: [Key: Color]] = [:]
        for r in ChestRarity.allCases {
            var m: [Key: Color] = [:]
            for (k, v) in palette(r) { m[k] = Color(hex: v) }
            out[r] = m
        }
        return out
    }()
}
